    def hook_length(n, k):
        return (n - k + 1) * (n - k) // 2

    def young_diagram(m, n):
        diag = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(1, m + 1):
            diag[i][i] = hook_length(i, 0)
            for j in range(1, min(i, n) + 1):
                diag[i][j] = diag[i - 1][j - 1] + hook_length(i, j)
        return diag

    def count_irreducible_components(diag):
        m, n = len(diag) - 1, len(diag[0]) - 1
        count = 0
        for i in range(m + 1):
            for j in range(n + 1):
                if diag[i][j] == 1:
                    count += 1
        return count

    def perm_matrix(n):
        matrix = [[0] * n for _ in range(n)]
        for i in range(n):
            matrix[i][(i + 1) % n] = 1
        return matrix

    def det_matrix(n):
        matrix = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if (i + j) % 2 == 0:
                    matrix[i][j] = 1
        return matrix

    def tensor_power(matrix, k):
        result = matrix
        for _ in range(1, k):
            result = [[sum(result[i][m] * matrix[m][j] for m in range(n)) for j in range(n)] for i in range(n)]
        return result

    n_values = [5, 10, 15, 20, 30, 40]
